"use strict";
(async()=>{
 const W=window.ArdennesWorkspaceHandle,R=window.CampaignRepository;
 const M=ArdennesCommand,root=document.getElementById('commandApp'),sources=Object.fromEntries([14,15].map(n=>['M'+n,window.PANZER_SITUATION_LIBRARY.find(d=>d.situation.number===n)]));
 if(!root)return;
 const hash=async d=>Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(JSON.stringify(d))))).map(b=>b.toString(16).padStart(2,'0')).join('');
 const hashes=Object.fromEntries(await Promise.all(Object.entries(sources).map(async([id,d])=>[id,await hash(d)])));
 let s=null,selected=null,error='',draft={main:'M14',reserve:'M14',delivery:'M14'},choice='supplied';
 try{const campaign=R.load();if(campaign)s=campaign.operation;}catch(e){error='Saved exercise could not be replayed: '+e.message;}
 const el=(tag,text)=>{const n=document.createElement(tag);if(text!==undefined)n.textContent=text;return n;};
 const button=(text,fn,disabled=false)=>{const b=el('button',text);b.disabled=disabled;b.onclick=fn;return b;};
 const select=(parent,id,label,options,value,change)=>{const l=el('label',label);l.htmlFor=id;const n=el('select');n.id=id;for(const [v,t] of options){const o=el('option',t);o.value=v;n.append(o);}n.value=value;n.onchange=()=>change(n.value);parent.append(l,n);return n;};
 const section=(title)=>{const n=el('section');n.append(el('h2',title));root.append(n);return n;};
 const act=(type,data={})=>{try{if(W&&!W.isLive())throw Error('Return to current time before issuing commands.');const world=R.get();const raw=world&&localStorage.getItem(CampaignWorld.KEY+world.id);if(raw){const live=CampaignWorld.validate(JSON.parse(raw),M).operation;if(live.id!==s.id||live.revision!==s.revision){s=live;throw Error('Exercise changed in another tab. Review current state and try again.');}}const next=M.execute(s,{id:crypto.randomUUID(),revision:s.revision,type,...data});R.saveOperation(next);s=next;error='';}catch(e){error=e.message;}render();if(type==='commit'&&!error)window.CampaignSituationIntegration.open(data.mission);};
 function newExercise(){if(s)R.archive();s=null;selected=null;error='';W?.reset();render();}
 function render(){if(W){const live=W.update(s,selected,draft,id=>{selected=id;render();},render,()=>act('advance'));if(W.renderSituation?.(root))return;if(!live){root.replaceChildren();const p=W.projection();const panel=section('Read-only map inspection');panel.append(el('p','Historical and forecast views cannot issue orders. Use Return to current time on the map toolbar.'));if(selected){const m=p.missions[selected];panel.append(el('p',M.names[selected]+' | '+m.state));}return;}}renderControls();}
 function renderControls(){root.replaceChildren();if(error){const e=el('p',error);e.setAttribute('role','alert');root.append(e);}
  if(!s){const start=section('Start an exercise');start.append(el('p','PL14 Bulge: Thrust and PL15 Elsenborn Ridge retain their source objectives. Shared command, stocks, reserve and timing below are authored exercise assumptions. Original cards and standalone saves are unchanged.'));
   let profile='operational',staff=10,test=false;
   select(start,'profile','Complexity',[['operational','Operational: choose reserve and deliveries'],['essentials','Essentials: automatic supply allocation']],profile,v=>profile=v);
   select(start,'staff','HQ staff preparation time (simulated)',[['10','Standard staff: 10 minutes'],['20','Reduced staff: 20 minutes']],String(staff),v=>staff=Number(v));
   const l=el('label'),cb=el('input');cb.type='checkbox';cb.onchange=()=>test=cb.checked;l.append(cb,document.createTextNode(' Isolated test session: enable outcome and disruption fixtures'));l.hidden=true;start.append(l,button('Start Ardennes exercise',()=>{s=M.initial(crypto.randomUUID(),profile,staff,test);R.saveOperation(s);render();}));return;
  }
  const bar=section('Command window');bar.append(el('p',M.clock(s.time)+' | '+s.profile+' | '+(s.test?'TEST SESSION':'Planning session')));bar.lastChild.className='clock';bar.append(el('p','Division: Ardennes Coordination HQ'+(selected?' / Regiment: '+M.names[selected]:' / Resource allocation')));
  if(!W&&s.queue.length){const at=Math.min(...s.queue.map(e=>e.at)),kinds=s.queue.filter(e=>e.at===at).map(e=>e.kind).join(', ');bar.append(button('Advance to '+M.clock(at)+' ('+kinds+')',()=>act('advance')));}else if(!W)bar.append(el('p','No scheduled events. Choose a mission action or start a new exercise.'));
  if(!s.plan){const panel=section('Parent HQ: allocate finite resources');panel.append(el('p','Stock: A14 ammunition, A15 ammunition, one fuel package F1. Reserve: two additional M10 counters. One transport, two packages per trip. Main effort receives its order first.'));
   select(panel,'main-effort','Main effort',Object.entries(M.names),draft.main,v=>{draft.main=v;render();});
   if(s.profile==='operational'){select(panel,'reserve','Reserve destination',[...Object.entries(M.names),['retain','Retain reserve']],draft.reserve,v=>{draft.reserve=v;render();});select(panel,'delivery','Delivery plan',[['M14','Support crossing defense first'],['M15','Support ridge defense first'],['guns','Guns first: ammunition to both missions']],draft.delivery,v=>{draft.delivery=v;render();});}else panel.append(el('p','Automatic policy: assign R1 and first ammunition/fuel delivery to the main effort; acknowledge orders on receipt.'));
   let p;try{p=M.preview(s,draft);const table=el('table');const head=el('tr');for(const x of ['Mission','Baseline ready','Supplied ready','Reinforced ready'])head.append(el('th',x));table.append(head);for(const r of p.rows){const row=el('tr');for(const x of [M.names[r.id],M.clock(r.baseline),M.clock(r.supplied),r.reinforced===null?'Not allocated':M.clock(r.reinforced)])row.append(el('td',x));table.append(row);}panel.append(table);for(const t of p.trips)panel.append(el('p',t.cargo.join(' + ')+' from West Supply Depot to '+(M.names[t.route]||'both receiving supply points')+'; dispatch '+M.clock(t.depart)+', receive '+M.clock(t.depart+30)+'.'));}catch(e){panel.append(el('p',e.message));}
   panel.append(button('Commit parent allocation',()=>act('allocate',{plan:draft,sourceHashes:hashes}),!p));
  }else if(!selected){const panel=section('Choose a subordinate mission');panel.append(el('p','Allocation locked. Mobile reserve: '+(M.names[s.plan.reserve]||'retained at headquarters')+'. Select a subordinate regiment.'));for(const [id,name]of Object.entries(M.names)){const m=s.missions[id];panel.append(button(name+' | '+m.state,()=>{selected=id;choice='supplied';render();}));}}
  else{const m=s.missions[selected],panel=section(M.names[selected]);panel.append(button('Return to parent missions',()=>{selected=null;render();}));panel.append(el('p','Order: '+m.state+' | '+(m.received?'Received; preparation '+M.clock(m.readyAt):'In transit')));
   panel.append(el('p',sources[selected].victory.join(' ')));
   if(m.committedAt===null){select(panel,'defense','Defense plan',[['baseline','Baseline defense: withhold one gun'],['supplied','Supplied defense: restore source gun'],['reinforced','Reinforced defense: source gun plus two R1 M10s']],choice,v=>{choice=v;render();});const reason=M.ready(s,selected,choice);panel.append(el('p',choice==='baseline'?'Difference: '+(selected==='M14'?'57 mm gun us-57mm-03':'105 mm howitzer us-105mm-02')+' withheld. Pending supply and reserve commitments remain reserved.':choice==='supplied'?'Difference: restore the withheld gun; no added reserve.':'Difference: restore withheld gun and add two authored R1 M10 counters. Original factors and German forces remain unchanged.'));panel.append(el('p',reason||'Ready to commit. Allowances are issued once; the roster becomes fixed.'));panel.append(button('Commit defense plan',()=>act('commit',{mission:selected,choice}),!!reason));}
   else{panel.append(el('h3','Committed Situation variant'),el('p',m.choice+' defense at '+M.clock(m.committedAt)+'. Deployment and inspection only. Combat execution is unavailable.'));const d=M.variant(s,selected,sources[selected]);panel.append(el('p',d.briefing.split('Source:')[0]),el('p','Allied '+d.totals.Allied+' / German '+d.totals.German+' counters.'));
    const a=el('a','Open committed Situation setup');a.className='action';a.textContent='Continue to Situation setup';a.href='#';a.onclick=e=>{e.preventDefault();window.CampaignSituationIntegration.continueToSetup(selected);};const world=CampaignWorld.bindMission(R.get(),selected,sources[selected],M);if(!R.get().missions[selected])R.save(world);const completion=el('p','Defense plan committed. Review the resulting Situation Card on the right, then continue here to deploy.');completion.setAttribute('role','status');panel.append(completion,a);
    if(s.test&&m.state==='Committed'){const test=el('section');test.className='test';test.append(el('h3','Test-only outcome simulator'),el('p','No combat is run. Fixed result fixture: objective held preserves both reserve counters; objective lost leaves one reserve survivor. Other losses are unknown. Fixture duration: 60 minutes.'));
     test.append(button('Schedule test outcome boundary',()=>act('fixture-clock',{mission:selected}),s.queue.some(e=>e.kind==='fixture-boundary')),button('Apply TEST outcome: held',()=>act('fixture',{mission:selected,outcome:'held'}),s.time<m.committedAt+60),button('Apply TEST outcome: lost',()=>act('fixture',{mission:selected,outcome:'lost'}),s.time<m.committedAt+60));panel.append(test);}
    if(m.state==='ReportPending')panel.append(el('p','Result reconciled. Superior report not delivered yet.'));
    if(m.report){panel.append(el('h3','Delivered TEST report'),el('p',m.report.held?'Objective held.':'Objective lost.'),el('p','Reported R1 survivors: '+m.report.reserveSurvivors+'. No second sortie allowance is available.'));if(m.state==='ReportDelivered')panel.append(button('Continue assigned defense',()=>act('assess',{mission:selected,action:'continue'}),!m.report.held),button('Request reinforcement',()=>act('assess',{mission:selected,action:'request'})),button('Record objective failure',()=>act('assess',{mission:selected,action:'failure'}),m.report.held));else panel.append(el('p','Assessment recorded: '+m.assessment));}
   }
  }
  const ledger=el('details');ledger.append(el('summary','Allocation, supply and event ledger'));for(const [id,custody]of Object.entries(s.stock))ledger.append(el('p',id+': '+custody));for(const t of s.trips)ledger.append(el('p',t.id+': '+t.status+' | '+t.cargo.join(', ')));for(const e of s.events)ledger.append(el('p',M.clock(e.at)+' '+e.text));root.append(ledger);
  if(s.test){const tools=el('details');tools.className='test';tools.append(el('summary','Test-only route and leadership fixtures'));for(const id of Object.keys(M.names))tools.append(button('Interrupt route '+id,()=>act('interrupt',{route:id})),button('Reopen route '+id,()=>act('reopen',{route:id})));for(const t of s.trips.filter(t=>t.status==='held'))tools.append(button('Recall '+t.id,()=>act('recall',{trip:t.id})));tools.append(button('Commander unavailable: test succession',()=>act('vacancy'),s.vacant));root.append(tools);}
  const notes=el('details');notes.append(el('summary','Personal notes (not orders)'));const area=el('textarea');area.setAttribute('aria-label','Personal notes');area.value=R.get().notes||'';area.onchange=()=>{const w=R.get();R.save({...w,notes:area.value});};notes.append(area);root.append(notes);
 }
 window.ArdennesSessionActions={startNew:newExercise,exportSave(){if(!s)throw Error('Start a campaign first.');const url=URL.createObjectURL(new Blob([JSON.stringify(R.get(),null,2)],{type:'application/json'}));const a=el('a');a.href=url;a.download='campaign-'+s.id+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);},archives(){return R.list();},restore(key){R.archive();s=R.open(key).operation;selected=null;W?.reset();render();}};
 render();
})().catch(e=>{const root=document.getElementById('commandApp');if(root)root.textContent='Exercise could not load: '+e.message;});
